export interface DirectoryEntry {
  id: string;
  label: string;
}

export interface NumberedEntry extends DirectoryEntry {
  position: number;
}

export interface DirectoryPage {
  page: number;
  pageSize: number;
  totalEntries: number;
  totalPages: number;
  entries: NumberedEntry[];
}

function validateEntries(entries: readonly DirectoryEntry[]): void {
  const ids = new Set<string>();
  for (const entry of entries) {
    if (typeof entry.id !== "string" || entry.id.length === 0 ||
        typeof entry.label !== "string" || entry.label.length === 0) {
      throw new TypeError("Invalid directory entry.");
    }
    if (ids.has(entry.id)) {
      throw new TypeError("Directory entry IDs must be unique.");
    }
    ids.add(entry.id);
  }
}

export function pageDirectory(
  entries: readonly DirectoryEntry[],
  page: number,
  pageSize: number,
  omittedIds: readonly string[] = [],
): DirectoryPage {
  validateEntries(entries);
  if (!Number.isInteger(page) || page < 1) {
    throw new RangeError("Page must be a positive integer.");
  }
  if (pageSize !== 10 && pageSize !== 20 && pageSize !== 50) {
    throw new RangeError("Unsupported page size.");
  }

  const omitted = new Set(omittedIds);
  const filtered = entries.filter((entry) => !omitted.has(entry.id));
  const totalEntries = filtered.length;
  const totalPages = Math.ceil(totalEntries / pageSize);
  const effectivePage = totalPages === 0 ? 1 : Math.min(page, totalPages);
  const start = (effectivePage - 1) * pageSize;
  const pageEntries = filtered.slice(start, start + pageSize).map((entry, index) => ({
    id: entry.id,
    label: entry.label,
    position: index + 1,
  }));

  return { page: effectivePage, pageSize, totalEntries, totalPages, entries: pageEntries };
}

export function omitDirectoryEntry(
  entries: readonly DirectoryEntry[],
  id: string,
): DirectoryEntry[] {
  validateEntries(entries);
  const index = entries.findIndex((entry) => entry.id === id);
  if (index < 0) {
    throw new RangeError("Directory entry not found.");
  }
  return entries.filter((_, current) => current !== index).map((entry) => ({ ...entry }));
}

